/bin/bash -lc "node check.js; node --check logic.js; node <<'NODE'
const assert = require('node:assert/strict');
const { merge_intervals } = require('./logic');
const intervals = Object.freeze([
  Object.freeze([9, 10]), Object.freeze([1, 5]),
  Object.freeze([2, 3]), Object.freeze([5, 7]),
  Object.freeze([8, 8]), Object.freeze([1, 5]),
]);
const result = merge_intervals(intervals);
assert.deepEqual(result, [[1, 7], [8, 8], [9, 10]]);
assert.deepEqual(merge_intervals([[2, 2], [2, 2]]), [[2, 2]]);
assert.deepEqual(merge_intervals([[4, 6]]), [[4, 6]]);
result[0][0] = 0;
assert.deepEqual(intervals[1], [1, 5]);
console.log('Additional interval checks passed');
NODE"

